/** @param {NS} ns */
export async function main(ns) {
  ns.print('Starting hacker script...');

  function bfsScan() {
    const visited = new Set(['home']);
    const queue = ['home'];
    while (queue.length > 0) {
      const node = queue.shift();
      let neighbors = [];
      try { neighbors = ns.scan(node); } catch(e) {}
      for (const n of neighbors) {
        if (!visited.has(n)) {
          visited.add(n);
          queue.push(n);
        }
      }
    }
    visited.delete('home');
    return [...visited];
  }

  function tryRoot(server) {
    if (ns.hasRootAccess(server)) return true;
    let ports = 0;
    try { ns.brutessh(server); ports++; } catch(e) {}
    try { ns.ftpcrack(server); ports++; } catch(e) {}
    try { ns.nuke(server); return ns.hasRootAccess(server); } catch(e) {}
    return false;
  }

  function getTargets(servers) {
    const hackLvl = ns.getHackingLevel();
    const targets = [];
    for (const s of servers) {
      try {
        if (!ns.hasRootAccess(s)) continue;
        const maxMoney = ns.getServerMaxMoney(s);
        if (maxMoney <= 0) continue;
        const reqLvl = ns.getServerRequiredHackingLevel(s);
        if (reqLvl > hackLvl) continue;
        const minSec = ns.getServerMinSecurityLevel(s);
        const score = maxMoney / (minSec || 1);
        targets.push({ s, score, maxMoney, minSec });
      } catch(e) {}
    }
    targets.sort((a, b) => b.score - a.score);
    return targets;
  }

  let servers = [];
  let lastScan = 0;
  let lastTargetPick = 0;
  let target = null;

  while (true) {
    const now = Date.now();

    // Re-scan every 30 seconds
    if (now - lastScan > 30000) {
      lastScan = now;
      try {
        servers = bfsScan();
        for (const s of servers) {
          try { tryRoot(s); } catch(e) {}
        }
        ns.print('Servers found: ' + servers.length);
      } catch(e) {}
    }

    // Re-pick target every 60 seconds
    if (now - lastTargetPick > 60000 || target === null) {
      lastTargetPick = now;
      try {
        const targets = getTargets(servers);
        if (targets.length > 0) {
          target = targets[0].s;
          ns.print('Target: ' + target + ' score=' + targets[0].score.toFixed(0));
        }
      } catch(e) {}
    }

    if (target === null) {
      await ns.sleep(5000);
      continue;
    }

    try {
      const minSec = ns.getServerMinSecurityLevel(target);
      const sec = ns.getServerSecurityLevel(target);
      const money = ns.getServerMoneyAvailable(target);
      const maxMoney = ns.getServerMaxMoney(target);

      if (sec > minSec + 5) {
        await ns.weaken(target);
      } else if (money < maxMoney * 0.75) {
        await ns.grow(target);
      } else {
        await ns.hack(target);
      }
    } catch(e) {
      ns.print('Error on target ' + target + ': ' + e);
      target = null;
      await ns.sleep(1000);
    }

    await ns.sleep(50);
  }
}

